reply:
```turtle
@prefix ht:   <http://example.org/onto/hypertension#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

ht: a owl:Ontology ;
    rdfs:label "Hypertension Ontology"@en ;
    skos:definition "An ontology modeling the classification, etiology, measurement, treatment, risk factors, and target-organ damage of hypertension as stated in the source corpus."@en .

#################################################################
# 1. MEASUREMENT AXIS
#################################################################

ht:BloodPressureReading a owl:Class ;
    rdfs:label "Blood Pressure Reading"@en ;
    skos:definition "A measured pair of systolic and diastolic values."@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] ,
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] .

ht:hasSystolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has systolic value"@en ;
    skos:definition "The maximum arterial pressure during one heartbeat, in mmHg."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:hasDiastolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diastolic value"@en ;
    skos:definition "The minimum arterial pressure between heartbeats, in mmHg."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:BloodPressureCategory a owl:Class ;
    rdfs:label "Blood Pressure Category"@en ;
    skos:definition "A classification band for a blood pressure reading defined by systolic and/or diastolic thresholds."@en ;
    rdfs:subClassOf ht:BloodPressureReading ;
    rdfs:comment "Modeled using the 2017 ACC/AHA scheme. Competing schemes use different thresholds: ESC/ESH (2018/2023) uses Optimal/Normal/High-normal/Grade 1-3 with a 140/90 mmHg diagnostic cut-point; JNC 7 uses Normal/Prehypertension/Stage 1 (140-159)/Stage 2 (>=160); WHO and ISH diagnose hypertension at 140/90 mmHg. These are noted here rather than modeled as parallel class trees."@en .

ht:NormalBloodPressure a owl:Class ;
    rdfs:label "Normal Blood Pressure"@en ;
    skos:definition "A blood pressure reading with systolic pressure less than 120 mmHg and diastolic pressure less than 80 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 120 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:ElevatedBloodPressure a owl:Class ;
    rdfs:label "Elevated Blood Pressure"@en ;
    skos:altLabel "Prehypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure 120 to 129 mmHg and diastolic pressure less than 80 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:minInclusive 120 ] [ xsd:maxInclusive 129 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:Stage1Hypertension a owl:Class ;
    rdfs:label "Stage 1 Hypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure 130 to 139 mmHg or diastolic pressure 80 to 89 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Class ; owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 130 ] [ xsd:maxInclusive 139 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 80 ] [ xsd:maxInclusive 89 ] ) ] ] ) ] ) ] .

ht:Stage2Hypertension a owl:Class ;
    rdfs:label "Stage 2 Hypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure 140 mmHg or greater or diastolic pressure 90 mmHg or greater."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Class ; owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 140 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 90 ] ) ] ] ) ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:NormalBloodPressure ht:ElevatedBloodPressure
    ht:Stage1Hypertension ht:Stage2Hypertension ) ] .

ht:AbnormalBloodPressureReading a owl:Class ;
    rdfs:label "Abnormal Blood Pressure Reading"@en ;
    skos:definition "A blood pressure reading that falls into the elevated, stage 1, or stage 2 category, i.e. above the normal range."@en ;
    rdfs:subClassOf ht:BloodPressureReading ;
    owl:equivalentClass [ owl:unionOf ( ht:ElevatedBloodPressure ht:Stage1Hypertension ht:Stage2Hypertension ) ] .

ht:SevereBloodPressureReading a owl:Class ;
    rdfs:label "Severe Blood Pressure Reading"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 180 mmHg or more or diastolic pressure of 120 mmHg or more, the conventional threshold for a hypertensive crisis."@en ;
    rdfs:subClassOf ht:BloodPressureReading ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Class ; owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 180 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 120 ] ) ] ] ) ] ) ] .

ht:OfficeBloodPressureReading a owl:Class ;
    rdfs:label "Office Blood Pressure Reading"@en ;
    skos:definition "A blood pressure reading obtained in a clinical office setting."@en ;
    rdfs:subClassOf ht:BloodPressureReading .

ht:OutOfOfficeBloodPressureReading a owl:Class ;
    rdfs:label "Out Of Office Blood Pressure Reading"@en ;
    skos:definition "A blood pressure reading obtained outside the clinical office setting."@en ;
    rdfs:subClassOf ht:BloodPressureReading .

ht:AmbulatoryBloodPressureReading a owl:Class ;
    rdfs:label "Ambulatory Blood Pressure Reading"@en ;
    skos:altLabel "ABPM"@en ;
    skos:definition "An out-of-office reading obtained by a device measuring blood pressure at regular intervals over the full sleep-wake cycle."@en ;
    rdfs:subClassOf ht:OutOfOfficeBloodPressureReading .

ht:HomeBloodPressureReading a owl:Class ;
    rdfs:label "Home Blood Pressure Reading"@en ;
    skos:altLabel "HBPM"@en ;
    skos:definition "An out-of-office reading obtained by patient self-measurement using a home blood pressure monitoring device."@en ;
    rdfs:subClassOf ht:OutOfOfficeBloodPressureReading .

owl:AllDisjointClasses [ owl:members ( ht:OfficeBloodPressureReading ht:OutOfOfficeBloodPressureReading ) ] .
owl:AllDisjointClasses [ owl:members ( ht:AmbulatoryBloodPressureReading ht:HomeBloodPressureReading ) ] .

ht:BloodPressureMeasurementMethod a owl:Class ;
    rdfs:label "Blood Pressure Measurement Method"@en ;
    skos:definition "A technique used to obtain a blood pressure reading."@en .

ht:AuscultatoryMethod a owl:Class ;
    rdfs:label "Auscultatory Method"@en ;
    skos:definition "A blood pressure measurement method using a stethoscope and sphygmomanometer to detect Korotkoff sounds."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

ht:OscillometricMethod a owl:Class ;
    rdfs:label "Oscillometric Method"@en ;
    skos:definition "A blood pressure measurement method using automated detection of cuff pressure oscillations."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

owl:AllDisjointClasses [ owl:members ( ht:AuscultatoryMethod ht:OscillometricMethod ) ] .

ht:hasMeasurementMethod a owl:ObjectProperty ;
    rdfs:label "has measurement method"@en ;
    skos:definition "Relates a blood pressure reading to the technique used to obtain it."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureMeasurementMethod .

ht:hasBloodPressureCategory a owl:ObjectProperty ;
    rdfs:label "has blood pressure category"@en ;
    skos:definition "Relates a blood pressure reading to the classification band it falls into."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureCategory .

#################################################################
# 2. HYPERTENSION (DISEASE)
#################################################################

ht:Hypertension a owl:Class ;
    rdfs:label "Hypertension"@en ;
    skos:altLabel "High Blood Pressure"@en ;
    skos:definition "A chronic medical condition of sustained elevation of arterial pressure."@en ;
    rdfs:comment "Guideline-threshold controversy: the 2017 ACC/AHA guideline diagnoses hypertension at a systolic pressure of 130 mmHg or more and/or diastolic of 80 mmHg or more, whereas ESC/ESH, JNC7, WHO, and ISH diagnose hypertension at 140/90 mmHg or more. Modeled with a single functional threshold property rather than per-guideline subclasses."@en .

ht:hasBloodPressureReading a owl:ObjectProperty ;
    rdfs:label "has blood pressure reading"@en ;
    skos:definition "Relates a hypertensive condition to a blood pressure reading that evidences it."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:BloodPressureReading .

ht:hasOfficeBloodPressureReading a owl:ObjectProperty ;
    rdfs:label "has office blood pressure reading"@en ;
    skos:definition "Relates a hypertensive condition to a reading taken in the clinical office."@en ;
    rdfs:subPropertyOf ht:hasBloodPressureReading ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:OfficeBloodPressureReading .

ht:hasOutOfOfficeBloodPressureReading a owl:ObjectProperty ;
    rdfs:label "has out of office blood pressure reading"@en ;
    skos:definition "Relates a hypertensive condition to a reading taken outside the clinical office."@en ;
    rdfs:subPropertyOf ht:hasBloodPressureReading ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:OutOfOfficeBloodPressureReading .

ht:hasDiagnosticSystolicThreshold a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diagnostic systolic threshold"@en ;
    skos:definition "The systolic blood pressure value, in mmHg, at or above which hypertension is diagnosed under a given clinical standard."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range xsd:integer ;
    rdfs:comment "Two competing values are documented in the corpus: 130 mmHg (2017 ACC/AHA) and 140 mmHg (ESC/ESH, JNC7, WHO, ISH)."@en .

ht:PrimaryHypertension a owl:Class ;
    rdfs:label "Primary Hypertension"@en ;
    skos:altLabel "Essential Hypertension"@en , "Idiopathic Hypertension"@en ;
    skos:definition "Hypertension with no single identifiable cause, arising from an interaction of genetic predisposition and environmental/lifestyle factors; accounts for approximately 85-95% of cases."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:SecondaryHypertension a owl:Class ;
    rdfs:label "Secondary Hypertension"@en ;
    skos:altLabel "Inessential Hypertension"@en ;
    skos:definition "Hypertension that is secondary to an identifiable, often treatable, underlying cause; accounts for approximately 5-15% of cases, with higher proportions in children and lower in older adults."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasSecondaryCause ; owl:someValuesFrom ht:SecondaryCause ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryHypertension ht:SecondaryHypertension ) ] .

ht:IsolatedSystolicHypertension a owl:Class ;
    rdfs:label "Isolated Systolic Hypertension"@en ;
    skos:altLabel "ISH"@en ;
    skos:definition "Hypertension characterized by a disproportionate rise in systolic pressure with a preserved or low diastolic pressure, producing a widened pulse pressure; predominant in older adults due to arterial stiffening."@en ;
    rdfs:subClassOf ht:Hypertension ;
    rdfs:comment "Traditionally defined as systolic pressure above 140 mmHg with diastolic below 90 mmHg; under the 2017 ACC/AHA guideline a systolic pressure of 130 mmHg is considered hypertensive at all ages."@en .

ht:WhiteCoatHypertension a owl:Class ;
    rdfs:label "White Coat Hypertension"@en ;
    skos:altLabel "White Coat Syndrome"@en , "WHT"@en ;
    skos:definition "A phenotype of consistently elevated office blood pressure with normal out-of-office blood pressure."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasOfficeBloodPressureReading ; owl:someValuesFrom ht:AbnormalBloodPressureReading ]
        [ a owl:Restriction ; owl:onProperty ht:hasOutOfOfficeBloodPressureReading ; owl:someValuesFrom ht:NormalBloodPressure ] ) ] .

ht:MaskedHypertension a owl:Class ;
    rdfs:label "Masked Hypertension"@en ;
    skos:altLabel "MH"@en ;
    skos:definition "A phenotype of normal office blood pressure with consistently elevated out-of-office blood pressure, the inverse of white coat hypertension."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasOfficeBloodPressureReading ; owl:someValuesFrom ht:NormalBloodPressure ]
        [ a owl:Restriction ; owl:onProperty ht:hasOutOfOfficeBloodPressureReading ; owl:someValuesFrom ht:AbnormalBloodPressureReading ] ) ] .

ht:ResistantHypertension a owl:Class ;
    rdfs:label "Resistant Hypertension"@en ;
    skos:definition "Blood pressure that remains uncontrolled despite adherence to three suitably dosed antihypertensive medications of different classes, one of which is a diuretic, after exclusion of the white coat effect; or blood pressure controlled only with four or more agents."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasAntihypertensive ; owl:minQualifiedCardinality 3 ; owl:onClass ht:Antihypertensive ]
        [ a owl:Restriction ; owl:onProperty ht:hasAntihypertensive ; owl:someValuesFrom ht:ThiazideDiuretic ] ) ] .

ht:HypertensiveCrisis a owl:Class ;
    rdfs:label "Hypertensive Crisis"@en ;
    skos:definition "A severe, acute elevation in blood pressure, conventionally a systolic pressure over 180 mmHg or a diastolic pressure over 120 mmHg."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasBloodPressureReading ; owl:someValuesFrom ht:SevereBloodPressureReading ] ) ] .

ht:HypertensiveUrgency a owl:Class ;
    rdfs:label "Hypertensive Urgency"@en ;
    skos:definition "A hypertensive crisis without evidence of acute target-organ damage, managed with gradual blood pressure reduction using oral medication."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis .

ht:HypertensiveEmergency a owl:Class ;
    rdfs:label "Hypertensive Emergency"@en ;
    skos:definition "A hypertensive crisis accompanied by acute hypertension-mediated target-organ damage, requiring immediate controlled reduction of blood pressure, typically with intravenous agents."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    owl:equivalentClass [ owl:intersectionOf ( ht:HypertensiveCrisis
        [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ; owl:someValuesFrom ht:TargetOrganDamage ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveUrgency ht:HypertensiveEmergency ) ] .

#################################################################
# 3. SECONDARY CAUSES
#################################################################

ht:SecondaryCause a owl:Class ;
    rdfs:label "Secondary Cause"@en ;
    skos:definition "An identifiable underlying condition, medication, or substance responsible for elevated blood pressure in secondary hypertension."@en .

ht:hasSecondaryCause a owl:ObjectProperty ;
    rdfs:label "has secondary cause"@en ;
    skos:definition "Relates secondary hypertension to its identifiable underlying cause."@en ;
    rdfs:domain ht:SecondaryHypertension ; rdfs:range ht:SecondaryCause .

ht:isSecondaryCauseOf a owl:ObjectProperty ;
    rdfs:label "is secondary cause of"@en ;
    skos:definition "Relates an underlying cause to the secondary hypertension it produces."@en ;
    owl:inverseOf ht:hasSecondaryCause ;
    rdfs:domain ht:SecondaryCause ; rdfs:range ht:SecondaryHypertension .

ht:RenalCause a owl:Class ;
    rdfs:label "Renal Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from kidney disease."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:RenalParenchymalDisease a owl:Class ;
    rdfs:label "Renal Parenchymal Disease"@en ;
    skos:definition "Disease of the kidney tissue itself, including diabetic nephropathy, glomerulonephritis, interstitial disorders, and polycystic kidney disease, the most common cause of secondary hypertension."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:RenovascularDisease a owl:Class ;
    rdfs:label "Renovascular Disease"@en ;
    skos:altLabel "Renovascular Hypertension"@en ;
    skos:definition "A renal cause of hypertension arising from obstruction or narrowing of a renal artery."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:RenalArteryStenosis a owl:Class ;
    rdfs:label "Renal Artery Stenosis"@en ;
    skos:definition "Narrowing of the renal artery producing renovascular hypertension."@en ;
    rdfs:subClassOf ht:RenovascularDisease .

owl:AllDisjointClasses [ owl:members ( ht:RenalParenchymalDisease ht:RenovascularDisease ) ] .

ht:EndocrineCause a owl:Class ;
    rdfs:label "Endocrine Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a hormonal disorder."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:PrimaryAldosteronism a owl:Class ;
    rdfs:label "Primary Aldosteronism"@en ;
    skos:altLabel "Conn's Syndrome"@en , "Hyperaldosteronism"@en ;
    skos:definition "An endocrine cause of hypertension resulting from autonomous overproduction of aldosterone by the adrenal glands; accounts for most endocrine-related secondary hypertension and is found in up to one in five resistant hypertension patients."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:Pheochromocytoma a owl:Class ;
    rdfs:label "Pheochromocytoma"@en ;
    skos:definition "An endocrine cause of hypertension due to a tumor that secretes excess norepinephrine and epinephrine, promoting vasoconstriction."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:CushingSyndrome a owl:Class ;
    rdfs:label "Cushing Syndrome"@en ;
    skos:definition "An endocrine cause of hypertension due to excess glucocorticoids."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:ThyroidDisease a owl:Class ;
    rdfs:label "Thyroid Disease"@en ;
    skos:definition "An endocrine cause of hypertension including hyperthyroidism and hypothyroidism."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:PrimaryHyperparathyroidism a owl:Class ;
    rdfs:label "Primary Hyperparathyroidism"@en ;
    skos:definition "An endocrine cause of secondary hypertension due to excess parathyroid hormone."@en ;
    rdfs:subClassOf ht:EndocrineCause .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryAldosteronism ht:Pheochromocytoma ht:CushingSyndrome ht:ThyroidDisease ht:PrimaryHyperparathyroidism ) ] .

ht:VascularCause a owl:Class ;
    rdfs:label "Vascular Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a structural vascular abnormality."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:AorticCoarctation a owl:Class ;
    rdfs:label "Aortic Coarctation"@en ;
    skos:altLabel "Coarctation Of The Aorta"@en ;
    skos:definition "A congenital narrowing of the aorta producing secondary hypertension, typically affecting younger patients."@en ;
    rdfs:subClassOf ht:VascularCause .

ht:ObstructiveSleepApnea a owl:Class ;
    rdfs:label "Obstructive Sleep Apnea"@en ;
    skos:altLabel "OSA"@en ;
    skos:definition "A sleep-related breathing disorder that is one of the most common causes of secondary hypertension."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:DrugInducedCause a owl:Class ;
    rdfs:label "Drug Induced Cause"@en ;
    skos:definition "A secondary cause of hypertension due to a medication or substance, including NSAIDs, sympathomimetic decongestants, stimulants, corticosteroids, licorice, oral contraceptives, cyclosporine, cocaine, and methamphetamine."@en ;
    rdfs:subClassOf ht:SecondaryCause .

owl:AllDisjointClasses [ owl:members ( ht:RenalCause ht:EndocrineCause ht:VascularCause ht:ObstructiveSleepApnea ht:DrugInducedCause ) ] .

#################################################################
# 4. TARGET ORGAN DAMAGE
#################################################################

ht:TargetOrganDamage a owl:Class ;
    rdfs:label "Target Organ Damage"@en ;
    skos:altLabel "Hypertension Mediated Organ Damage"@en ;
    skos:definition "Structural or functional injury to an organ system resulting from chronic or acute hypertension."@en .

ht:hasTargetOrganDamage a owl:ObjectProperty ;
    rdfs:label "has target organ damage"@en ;
    skos:definition "Relates a hypertensive condition to organ damage it has produced."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:TargetOrganDamage .

ht:isTargetOrganDamageOf a owl:ObjectProperty ;
    rdfs:label "is target organ damage of"@en ;
    owl:inverseOf ht:hasTargetOrganDamage ;
    skos:definition "Relates organ damage to the hypertensive condition that produced it."@en ;
    rdfs:domain ht:TargetOrganDamage ; rdfs:range ht:Hypertension .

ht:HypertensiveHeartDisease a owl:Class ;
    rdfs:label "Hypertensive Heart Disease"@en ;
    skos:definition "Structural and functional changes in the left ventricle, left atrium, and coronary arteries resulting from chronic blood pressure elevation."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:LeftVentricularHypertrophy a owl:Class ;
    rdfs:label "Left Ventricular Hypertrophy"@en ;
    skos:definition "Thickening of the left ventricular wall in compensatory response to chronic pressure overload; the hallmark structural manifestation of hypertensive cardiac damage."@en ;
    rdfs:subClassOf ht:HypertensiveHeartDisease .

ht:RetinalFinding a owl:Class ;
    rdfs:label "Retinal Finding"@en ;
    skos:definition "A specific retinal vascular abnormality observed on fundoscopic examination resulting from hypertensive damage."@en .

ht:ArteriolarNarrowing a owl:Class ;
    rdfs:label "Arteriolar Narrowing"@en ;
    skos:definition "Generalized or focal narrowing of the retinal arterioles."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:ArteriovenousNicking a owl:Class ;
    rdfs:label "Arteriovenous Nicking"@en ;
    skos:altLabel "AV Nicking"@en , "AV Nipping"@en ;
    skos:definition "Compression of a retinal vein where it is crossed by a sclerotic arteriole."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:RetinalHemorrhage a owl:Class ;
    rdfs:label "Retinal Hemorrhage"@en ;
    skos:altLabel "Flame Hemorrhage"@en , "Blot Hemorrhage"@en ;
    skos:definition "Bleeding into the retinal tissue due to breakdown of the blood-retinal barrier."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:CottonWoolSpot a owl:Class ;
    rdfs:label "Cotton Wool Spot"@en ;
    skos:definition "A retinal ischemic lesion appearing as a pale, fluffy patch."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:HardExudate a owl:Class ;
    rdfs:label "Hard Exudate"@en ;
    skos:definition "A deposit of lipid leaked from damaged retinal vessels."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:Papilledema a owl:Class ;
    rdfs:label "Papilledema"@en ;
    skos:altLabel "Optic Disc Edema"@en ;
    skos:definition "Swelling of the optic disc, the most severe retinal finding, indicating malignant hypertension."@en ;
    rdfs:subClassOf ht:RetinalFinding .

owl:AllDisjointClasses [ owl:members ( ht:ArteriolarNarrowing ht:ArteriovenousNicking ht:RetinalHemorrhage ht:CottonWoolSpot ht:HardExudate ht:Papilledema ) ] .

ht:hasRetinalFinding a owl:ObjectProperty ;
    rdfs:label "has retinal finding"@en ;
    skos:definition "Relates hypertensive retinopathy to a specific retinal finding it presents."@en ;
    rdfs:domain ht:HypertensiveRetinopathy ; rdfs:range ht:RetinalFinding .

ht:isRetinalFindingOf a owl:ObjectProperty ;
    rdfs:label "is retinal finding of"@en ;
    owl:inverseOf ht:hasRetinalFinding ;
    skos:definition "Relates a retinal finding to the hypertensive retinopathy it evidences."@en ;
    rdfs:domain ht:RetinalFinding ; rdfs:range ht:HypertensiveRetinopathy .

ht:HypertensiveRetinopathy a owl:Class ;
    rdfs:label "Hypertensive Retinopathy"@en ;
    skos:definition "Damage to the retina and retinal circulation due to high blood pressure, evidenced by characteristic retinal findings."@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    owl:equivalentClass [ owl:intersectionOf ( ht:TargetOrganDamage
        [ a owl:Restriction ; owl:onProperty ht:hasRetinalFinding ; owl:someValuesFrom ht:RetinalFinding ] ) ] .

ht:HypertensiveKidneyDisease a owl:Class ;
    rdfs:label "Hypertensive Kidney Disease"@en ;
    skos:definition "Damage to kidney tissue, including small blood vessels, glomeruli, tubules, and interstitium, due to chronic high blood pressure."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:Nephrosclerosis a owl:Class ;
    rdfs:label "Nephrosclerosis"@en ;
    skos:definition "Hardening and thickening of renal vessels and glomeruli caused by chronic hypertension, reducing blood and oxygen supply to kidney tissue; the characteristic lesion of hypertensive nephropathy."@en ;
    rdfs:subClassOf ht:HypertensiveKidneyDisease .

ht:HypertensiveEncephalopathy a owl:Class ;
    rdfs:label "Hypertensive Encephalopathy"@en ;
    skos:definition "Brain swelling and dysfunction caused by severely elevated blood pressure, presenting with headache, confusion, or visual disturbance."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:Stroke a owl:Class ;
    rdfs:label "Stroke"@en ;
    skos:definition "Ischemic or hemorrhagic cerebrovascular injury resulting from hypertensive damage to cerebral vessels."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveHeartDisease ht:HypertensiveRetinopathy ht:HypertensiveKidneyDisease ht:HypertensiveEncephalopathy ht:Stroke ) ] .

#################################################################
# 5. ANTIHYPERTENSIVE DRUG CLASSES
#################################################################

ht:Antihypertensive a owl:Class ;
    rdfs:label "Antihypertensive"@en ;
    skos:definition "A class of medication used to lower blood pressure."@en .

ht:hasAntihypertensive a owl:ObjectProperty ;
    rdfs:label "has antihypertensive"@en ;
    skos:definition "Relates a hypertensive condition to a class of antihypertensive medication used in its treatment."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:Antihypertensive .

ht:isAntihypertensiveOf a owl:ObjectProperty ;
    rdfs:label "is antihypertensive of"@en ;
    owl:inverseOf ht:hasAntihypertensive ;
    skos:definition "Relates an antihypertensive drug class to the hypertensive condition it treats."@en ;
    rdfs:domain ht:Antihypertensive ; rdfs:range ht:Hypertension .

ht:ThiazideDiuretic a owl:Class ;
    rdfs:label "Thiazide Diuretic"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks sodium reabsorption in the distal convoluted tubule, promoting natriuresis and diuresis and reducing intravascular volume."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:AngiotensinConvertingEnzymeInhibitor a owl:Class ;
    rdfs:label "Angiotensin Converting Enzyme Inhibitor"@en ;
    skos:altLabel "ACE Inhibitor"@en , "ACEI"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits the angiotensin-converting enzyme, decreasing angiotensin II production and increasing bradykinin, producing vasodilation."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:AngiotensinReceptorBlocker a owl:Class ;
    rdfs:label "Angiotensin Receptor Blocker"@en ;
    skos:altLabel "Angiotensin II Receptor Blocker"@en , "ARB"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks the binding of angiotensin II to its AT1 receptor."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:CalciumChannelBlocker a owl:Class ;
    rdfs:label "Calcium Channel Blocker"@en ;
    skos:altLabel "CCB"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits calcium entry into cardiac and vascular smooth muscle cells via L-type voltage-gated calcium channels."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:DihydropyridineCalciumChannelBlocker a owl:Class ;
    rdfs:label "Dihydropyridine Calcium Channel Blocker"@en ;
    skos:definition "A calcium channel blocker subtype that acts predominantly on vascular smooth muscle, causing peripheral vasodilation, and is preferred for hypertension treatment."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

ht:NonDihydropyridineCalciumChannelBlocker a owl:Class ;
    rdfs:label "Non Dihydropyridine Calcium Channel Blocker"@en ;
    skos:definition "A calcium channel blocker subtype, such as verapamil or diltiazem, that primarily affects cardiac contractility and conduction and is better suited to managing arrhythmias."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

owl:AllDisjointClasses [ owl:members ( ht:DihydropyridineCalciumChannelBlocker ht:NonDihydropyridineCalciumChannelBlocker ) ] .

ht:BetaBlocker a owl:Class ;
    rdfs:label "Beta Blocker"@en ;
    skos:definition "An antihypertensive drug class that inhibits catecholamine binding to beta-adrenergic receptors, reducing heart rate, cardiac contractility, and renin release; no longer first-line for uncomplicated hypertension but retained for patients with a compelling cardiac indication."@en ;
    rdfs:subClassOf ht:Antihypertensive .

owl:AllDisjointClasses [ owl:members ( ht:ThiazideDiuretic ht:AngiotensinConvertingEnzymeInhibitor ht:AngiotensinReceptorBlocker ht:CalciumChannelBlocker ht:BetaBlocker ) ] .

#################################################################
# 6. RISK FACTORS
#################################################################

ht:RiskFactor a owl:Class ;
    rdfs:label "Risk Factor"@en ;
    skos:definition "A factor associated with increased likelihood of developing hypertension."@en .

ht:hasRiskFactor a owl:ObjectProperty ;
    rdfs:label "has risk factor"@en ;
    skos:definition "Relates a hypertensive condition to a factor contributing to its risk."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:RiskFactor .

ht:isRiskFactorOf a owl:ObjectProperty ;
    rdfs:label "is risk factor of"@en ;
    owl:inverseOf ht:hasRiskFactor ;
    skos:definition "Relates a risk factor to the hypertensive condition it contributes to."@en ;
    rdfs:domain ht:RiskFactor ; rdfs:range ht:Hypertension .

ht:ModifiableRiskFactor a owl:Class ;
    rdfs:label "Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that can be changed through behavioral or lifestyle intervention."@en ;
    rdfs:subClassOf ht:RiskFactor .

ht:NonModifiableRiskFactor a owl:Class ;
    rdfs:label "Non Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that cannot be changed, such as age, sex, race, or family history."@en ;
    rdfs:subClassOf ht:RiskFactor .

owl:AllDisjointClasses [ owl:members ( ht:ModifiableRiskFactor ht:NonModifiableRiskFactor ) ] .

ht:SaltIntake a owl:Class ;
    rdfs:label "Salt Intake"@en ;
    skos:definition "Dietary sodium consumption; excess salt intake is a modifiable risk factor for hypertension, and roughly 50-60% of patients are salt sensitive."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:Obesity a owl:Class ;
    rdfs:label "Obesity"@en ;
    skos:definition "Excess body weight, a modifiable risk factor for hypertension; weight reduction can lower systolic pressure by 5-20 mmHg."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:Smoking a owl:Class ;
    rdfs:label "Smoking"@en ;
    skos:definition "Tobacco use, a modifiable risk factor for hypertension."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:PhysicalInactivity a owl:Class ;
    rdfs:label "Physical Inactivity"@en ;
    skos:definition "Lack of regular exercise, a modifiable risk factor for hypertension."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:AlcoholUse a owl:Class ;
    rdfs:label "Alcohol Use"@en ;
    skos:definition "Consumption of alcohol; increased alcohol intake is associated with higher blood pressure and is a modifiable risk factor."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

owl:AllDisjointClasses [ owl:members ( ht:SaltIntake ht:Obesity ht:Smoking ht:PhysicalInactivity ht:AlcoholUse ) ] .

ht:Age a owl:Class ;
    rdfs:label "Age"@en ;
    skos:definition "Advancing age, a non-modifiable risk factor for hypertension; prevalence rises to roughly 60% of individuals above age 60."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:Sex a owl:Class ;
    rdfs:label "Sex"@en ;
    skos:definition "Biological sex, a non-modifiable risk factor influencing hypertension risk and treatment selection."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:Race a owl:Class ;
    rdfs:label "Race"@en ;
    skos:definition "Racial background, a non-modifiable risk factor that also influences treatment selection, with different first-line recommendations for Black and non-Black populations."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:FamilyHistory a owl:Class ;
    rdfs:label "Family History"@en ;
    skos:definition "A family history of hypertension, a non-modifiable risk factor."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:GeneticPredisposition a owl:Class ;
    rdfs:label "Genetic Predisposition"@en ;
    skos:definition "Inherited genetic variants contributing to hypertension risk; more than 2,000 common variants with small individual effects have been identified."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

owl:AllDisjointClasses [ owl:members ( ht:Age ht:Sex ht:Race ht:FamilyHistory ht:GeneticPredisposition ) ] .

#################################################################
# 7. TOP-LEVEL KIND DISJOINTNESS
#################################################################

owl:AllDisjointClasses [ owl:members (
    ht:BloodPressureReading
    ht:Hypertension
    ht:Antihypertensive
    ht:SecondaryCause
    ht:TargetOrganDamage
    ht:RiskFactor
    ht:RetinalFinding
    ht:BloodPressureMeasurementMethod
) ] .
