```turtle
@prefix ht:   <http://example.org/onto/hypertension#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

ht: a owl:Ontology ;
    rdfs:label "Hypertension Ontology"@en ;
    rdfs:comment "An ontology of hypertension classification, etiology, measurement, treatment, risk factors and target-organ damage, modeled from a mixed clinical/encyclopedic corpus. A single ACC/AHA-2017 blood-pressure category scheme is modeled; competing guideline thresholds (ESC/ESH, JNC7/8, WHO, NICE, ISH) are noted in comments rather than as parallel class trees."@en .

#################################################################
# TOP-LEVEL DISJOINTNESS
#################################################################

owl:AllDisjointClasses [ owl:members ( ht:BloodPressureReading ht:Hypertension ht:Antihypertensive ht:SecondaryCause ht:TargetOrganDamage ht:RiskFactor ) ] .

#################################################################
# MEASUREMENT AXIS
#################################################################

ht:BloodPressureReading a owl:Class ;
    rdfs:label "Blood Pressure Reading"@en ;
    skos:definition "A measured pair of systolic and diastolic values, expressed in millimetres of mercury, taken at a point in time."@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] ,
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] .

ht:hasSystolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has systolic value"@en ;
    skos:definition "The maximum arterial pressure during one heartbeat, in mmHg."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:hasDiastolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diastolic value"@en ;
    skos:definition "The minimum arterial pressure between heartbeats, in mmHg."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:hasBloodPressureCategory a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has blood pressure category"@en ;
    skos:definition "Relates a blood pressure reading to the single ACC/AHA-2017 category realized by its systolic and/or diastolic values."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureCategory .

ht:isBloodPressureCategoryOf a owl:ObjectProperty ;
    rdfs:label "is blood pressure category of"@en ;
    skos:definition "Inverse of has blood pressure category."@en ;
    owl:inverseOf ht:hasBloodPressureCategory ;
    rdfs:domain ht:BloodPressureCategory ; rdfs:range ht:BloodPressureReading .

ht:hasBloodPressureReading a owl:ObjectProperty ;
    rdfs:label "has blood pressure reading"@en ;
    skos:definition "Relates a hypertension-related condition to a blood pressure reading associated with it."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:BloodPressureReading .

ht:hasOfficeBloodPressureReading a owl:ObjectProperty ;
    rdfs:label "has office blood pressure reading"@en ;
    skos:definition "Relates a hypertension-related condition to a blood pressure reading obtained in a clinic/office setting."@en ;
    rdfs:subPropertyOf ht:hasBloodPressureReading ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:BloodPressureReading .

ht:hasOutOfOfficeBloodPressureReading a owl:ObjectProperty ;
    rdfs:label "has out of office blood pressure reading"@en ;
    skos:definition "Relates a hypertension-related condition to a blood pressure reading obtained outside the clinic, e.g. by home or ambulatory monitoring."@en ;
    rdfs:subPropertyOf ht:hasBloodPressureReading ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:BloodPressureReading .

#################################################################
# BLOOD PRESSURE CATEGORIES (ACC/AHA 2017)
#################################################################

ht:BloodPressureCategory a owl:Class ;
    rdfs:label "Blood Pressure Category"@en ;
    skos:definition "One of the four adult office blood-pressure bands defined by the 2017 ACC/AHA guideline: Normal, Elevated, Stage 1 Hypertension, Stage 2 Hypertension."@en ;
    rdfs:subClassOf ht:BloodPressureReading ;
    rdfs:comment "Competing guideline schemes (JNC7 Normal/Prehypertension/Stage1/Stage2 at 140/90; ESC/ESH 2018/2023 Optimal/Normal/High-normal/Grade1-3 at 140/90; WHO and ISH at 140/90; NICE NG136 Stage1/2/Severe) are not modeled as separate class trees; only the 2017 ACC/AHA scheme is modeled."@en .

ht:NormalBloodPressure a owl:Class ;
    rdfs:label "Normal Blood Pressure"@en ;
    skos:definition "A blood pressure reading with systolic pressure less than 120 mmHg and diastolic pressure less than 80 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 120 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] ;
    rdfs:comment "The American Heart Association/ACC place the normal threshold under 120/80 mmHg; the European Society of Cardiology (2024) places it under 120/70 mmHg - a conflict noted but not separately modeled."@en .

ht:ElevatedBloodPressure a owl:Class ;
    rdfs:label "Elevated Blood Pressure"@en ;
    skos:altLabel "Prehypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 120 to 129 mmHg and diastolic pressure less than 80 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:minInclusive 120 ] [ xsd:maxInclusive 129 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] ;
    rdfs:comment "This category was previously termed prehypertension under JNC7 (120-139/80-89). The ACC/AHA 2017 scheme reclassified part of that range as Elevated and part as Stage 1 Hypertension."@en .

ht:Stage1Hypertension a owl:Class ;
    rdfs:label "Stage 1 Hypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 130 to 139 mmHg or diastolic pressure of 80 to 89 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:unionOf (
        [ owl:intersectionOf ( ht:BloodPressureReading
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 130 ] [ xsd:maxInclusive 139 ] ) ] ] ) ]
        [ owl:intersectionOf ( ht:BloodPressureReading
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 80 ] [ xsd:maxInclusive 89 ] ) ] ] ) ]
    ) ] .

ht:Stage2Hypertension a owl:Class ;
    rdfs:label "Stage 2 Hypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 140 mmHg or greater, or diastolic pressure of 90 mmHg or greater."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:unionOf (
        [ owl:intersectionOf ( ht:BloodPressureReading
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 140 ] ) ] ] ) ]
        [ owl:intersectionOf ( ht:BloodPressureReading
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 90 ] ) ] ] ) ]
    ) ] ;
    rdfs:comment "When systolic and diastolic values fall into different categories, the corpus states that the higher category is used to classify the individual."@en .

owl:AllDisjointClasses [ owl:members ( ht:NormalBloodPressure ht:ElevatedBloodPressure ht:Stage1Hypertension ht:Stage2Hypertension ) ] .

#################################################################
# MEASUREMENT METHOD / SETTING
#################################################################

ht:BloodPressureMeasurementMethod a owl:Class ;
    rdfs:label "Blood Pressure Measurement Method"@en ;
    skos:definition "A technique used to obtain a blood pressure reading."@en .

ht:AuscultatoryMethod a owl:Class ;
    rdfs:label "Auscultatory Method"@en ;
    skos:definition "A blood pressure measurement method using a stethoscope and sphygmomanometer to listen for Korotkoff sounds as cuff pressure is released."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

ht:OscillometricMethod a owl:Class ;
    rdfs:label "Oscillometric Method"@en ;
    skos:definition "A blood pressure measurement method that calculates systolic, diastolic, and mean arterial pressure from oscillations in cuff pressure, used in automated devices."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

owl:AllDisjointClasses [ owl:members ( ht:AuscultatoryMethod ht:OscillometricMethod ) ] .

ht:BloodPressureMeasurementSetting a owl:Class ;
    rdfs:label "Blood Pressure Measurement Setting"@en ;
    skos:definition "The context in which a blood pressure reading is obtained."@en .

ht:OfficeBloodPressureMeasurement a owl:Class ;
    rdfs:label "Office Blood Pressure Measurement"@en ;
    skos:definition "Blood pressure measurement taken in a clinic or office setting."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementSetting .

ht:HomeBloodPressureMonitoring a owl:Class ;
    rdfs:label "Home Blood Pressure Monitoring"@en ;
    skos:altLabel "HBPM"@en ;
    skos:definition "Patient self-measurement of blood pressure at home, used to detect white coat and masked hypertension."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementSetting .

ht:AmbulatoryBloodPressureMonitoring a owl:Class ;
    rdfs:label "Ambulatory Blood Pressure Monitoring"@en ;
    skos:altLabel "ABPM"@en ;
    skos:definition "Blood pressure measured at regular intervals over a full 24-hour sleep-wake cycle outside the clinical setting."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementSetting .

owl:AllDisjointClasses [ owl:members ( ht:OfficeBloodPressureMeasurement ht:HomeBloodPressureMonitoring ht:AmbulatoryBloodPressureMonitoring ) ] .

ht:hasMeasurementMethod a owl:ObjectProperty ;
    rdfs:label "has measurement method"@en ;
    skos:definition "Relates a blood pressure reading to the technique used to obtain it."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureMeasurementMethod .

ht:hasMeasurementSetting a owl:ObjectProperty ;
    rdfs:label "has measurement setting"@en ;
    skos:definition "Relates a blood pressure reading to the context in which it was obtained."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureMeasurementSetting .

#################################################################
# HYPERTENSION (DISEASE) CORE
#################################################################

ht:Hypertension a owl:Class ;
    rdfs:label "Hypertension"@en ;
    skos:altLabel "High Blood Pressure"@en ;
    skos:definition "A chronic medical condition characterized by sustained elevation of arterial pressure."@en ;
    rdfs:comment "The diagnostic systolic threshold is genuinely contested: the 2017 ACC/AHA guideline sets it at 130 mmHg, whereas JNC7, WHO, ESC/ESH (2018/2023) and ISH (2020) retain 140 mmHg. Modeled with a single functional property hasDiagnosticSystolicThreshold rather than per-guideline subclasses."@en .

ht:hasDiagnosticSystolicThreshold a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diagnostic systolic threshold"@en ;
    skos:definition "The systolic value, in mmHg, at or above which a guideline diagnoses hypertension."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range xsd:integer ;
    rdfs:comment "Competing stated values: 130 (ACC/AHA 2017) and 140 (ESC/ESH, JNC7, WHO, ISH)."@en .

ht:PrimaryHypertension a owl:Class ;
    rdfs:label "Primary Hypertension"@en ;
    skos:altLabel "Essential Hypertension"@en , "Idiopathic Hypertension"@en ;
    skos:definition "Hypertension with no single identifiable cause, arising from a complex interaction of genetic and environmental factors; accounts for approximately 85-95% of cases."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:SecondaryHypertension a owl:Class ;
    rdfs:label "Secondary Hypertension"@en ;
    skos:altLabel "Inessential Hypertension"@en ;
    skos:definition "Hypertension that is secondary to a specific, identifiable, and often treatable underlying cause; accounts for approximately 5-15% of cases."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasSecondaryCause ; owl:someValuesFrom ht:SecondaryCause ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryHypertension ht:SecondaryHypertension ) ] .

ht:hasSecondaryCause a owl:ObjectProperty ;
    rdfs:label "has secondary cause"@en ;
    skos:definition "Relates a case of secondary hypertension to its identifiable underlying cause."@en ;
    rdfs:domain ht:SecondaryHypertension ; rdfs:range ht:SecondaryCause .

ht:isSecondaryCauseOf a owl:ObjectProperty ;
    rdfs:label "is secondary cause of"@en ;
    skos:definition "Inverse of has secondary cause."@en ;
    owl:inverseOf ht:hasSecondaryCause ;
    rdfs:domain ht:SecondaryCause ; rdfs:range ht:SecondaryHypertension .

#################################################################
# CLINICAL PHENOTYPES OF HYPERTENSION
#################################################################

ht:IsolatedSystolicHypertension a owl:Class ;
    rdfs:label "Isolated Systolic Hypertension"@en ;
    skos:definition "Hypertension characterized by a systolic pressure of 140 mmHg or more with a diastolic pressure below 90 mmHg, producing a widened pulse pressure; the predominant form of hypertension in older adults, usually due to arterial stiffening."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasBloodPressureReading ; owl:someValuesFrom
            [ owl:intersectionOf ( ht:BloodPressureReading
                [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                    [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                      owl:withRestrictions ( [ xsd:minInclusive 140 ] ) ] ]
                [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                    [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                      owl:withRestrictions ( [ xsd:maxExclusive 90 ] ) ] ] ) ] ] ) ] ;
    rdfs:comment "The 2017 ACC/AHA guideline lowers the hypertensive systolic threshold to 130 mmHg at all ages, which would alter this traditional 140 mmHg criterion; the traditional 140 mmHg definition is modeled as it is the one explicitly used to define the condition in the corpus."@en .

ht:WhiteCoatHypertension a owl:Class ;
    rdfs:label "White Coat Hypertension"@en ;
    skos:altLabel "White Coat Syndrome"@en , "WHT"@en ;
    skos:definition "A phenotype of labile hypertension in which office blood pressure is consistently elevated but out-of-office blood pressure is normal."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasOfficeBloodPressureReading ; owl:someValuesFrom
            [ owl:unionOf ( ht:ElevatedBloodPressure ht:Stage1Hypertension ht:Stage2Hypertension ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasOutOfOfficeBloodPressureReading ; owl:someValuesFrom ht:NormalBloodPressure ] ) ] .

ht:MaskedHypertension a owl:Class ;
    rdfs:label "Masked Hypertension"@en ;
    skos:altLabel "MH"@en ;
    skos:definition "A phenotype of hypertension in which office blood pressure is normal but out-of-office blood pressure is consistently elevated; the inverse of white coat hypertension."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasOfficeBloodPressureReading ; owl:someValuesFrom ht:NormalBloodPressure ]
        [ a owl:Restriction ; owl:onProperty ht:hasOutOfOfficeBloodPressureReading ; owl:someValuesFrom
            [ owl:unionOf ( ht:ElevatedBloodPressure ht:Stage1Hypertension ht:Stage2Hypertension ) ] ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:WhiteCoatHypertension ht:MaskedHypertension ) ] .

ht:ResistantHypertension a owl:Class ;
    rdfs:label "Resistant Hypertension"@en ;
    skos:definition "Blood pressure that remains uncontrolled despite adherence to at least three suitably dosed antihypertensive medications of different classes, one of which is a diuretic, after exclusion of the white coat effect; also includes blood pressure controlled only with four or more agents."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasAntihypertensive ; owl:minQualifiedCardinality "3"^^xsd:nonNegativeInteger ; owl:onClass ht:Antihypertensive ]
        [ a owl:Restriction ; owl:onProperty ht:hasAntihypertensive ; owl:someValuesFrom ht:ThiazideDiuretic ] ) ] .

#################################################################
# HYPERTENSIVE CRISIS
#################################################################

ht:HypertensiveCrisis a owl:Class ;
    rdfs:label "Hypertensive Crisis"@en ;
    skos:definition "A severe, acute elevation of blood pressure, commonly defined as systolic pressure of 180 mmHg or more or diastolic pressure of 120 mmHg or more; divided into hypertensive urgency and hypertensive emergency according to the presence of acute target-organ damage."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasBloodPressureReading ; owl:someValuesFrom
            [ owl:unionOf (
                [ owl:intersectionOf ( ht:BloodPressureReading
                    [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                        [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                          owl:withRestrictions ( [ xsd:minInclusive 180 ] ) ] ] ) ]
                [ owl:intersectionOf ( ht:BloodPressureReading
                    [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                        [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                          owl:withRestrictions ( [ xsd:minInclusive 120 ] ) ] ] ) ]
            ) ] ] ) ] .

ht:HypertensiveUrgency a owl:Class ;
    rdfs:label "Hypertensive Urgency"@en ;
    skos:definition "A hypertensive crisis without evidence of acute target-organ damage, managed by gradual oral reduction of blood pressure over hours to days."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis .

ht:HypertensiveEmergency a owl:Class ;
    rdfs:label "Hypertensive Emergency"@en ;
    skos:definition "A hypertensive crisis accompanied by acute hypertension-mediated target-organ damage, requiring prompt controlled reduction of blood pressure, typically with intravenous agents."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    owl:equivalentClass [ owl:intersectionOf ( ht:HypertensiveCrisis
        [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ; owl:someValuesFrom ht:TargetOrganDamage ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveUrgency ht:HypertensiveEmergency ) ] .

ht:hasTargetOrganDamage a owl:ObjectProperty ;
    rdfs:label "has target organ damage"@en ;
    skos:definition "Relates a hypertensive condition to a form of acute or chronic organ injury it has caused."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:TargetOrganDamage .

ht:isTargetOrganDamageOf a owl:ObjectProperty ;
    rdfs:label "is target organ damage of"@en ;
    skos:definition "Inverse of has target organ damage."@en ;
    owl:inverseOf ht:hasTargetOrganDamage ;
    rdfs:domain ht:TargetOrganDamage ; rdfs:range ht:Hypertension .

#################################################################
# SECONDARY CAUSES
#################################################################

ht:SecondaryCause a owl:Class ;
    rdfs:label "Secondary Cause"@en ;
    skos:definition "An identifiable underlying medical condition, vascular abnormality, or substance that produces secondary hypertension."@en .

ht:RenalCause a owl:Class ;
    rdfs:label "Renal Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from kidney disease, the most common category of secondary cause."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:RenalParenchymalDisease a owl:Class ;
    rdfs:label "Renal Parenchymal Disease"@en ;
    skos:definition "Disease of the kidney tissue itself, including diabetic nephropathy, glomerulonephritis, interstitial disorders, polycystic kidney disease, and lupus nephritis, causing secondary hypertension."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:RenovascularDisease a owl:Class ;
    rdfs:label "Renovascular Disease"@en ;
    skos:altLabel "Renovascular Hypertension"@en ;
    skos:definition "Hypertension arising from obstruction or stenosis of a renal artery."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:RenalArteryStenosis a owl:Class ;
    rdfs:label "Renal Artery Stenosis"@en ;
    skos:definition "Narrowing of the renal artery, the principal cause of renovascular disease and a recognized cause of isolated systolic hypertension and resistant hypertension when atherosclerotic."@en ;
    rdfs:subClassOf ht:RenovascularDisease .

ht:EndocrineCause a owl:Class ;
    rdfs:label "Endocrine Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a hormone-secreting disorder."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:PrimaryAldosteronism a owl:Class ;
    rdfs:label "Primary Aldosteronism"@en ;
    skos:altLabel "Conn's Syndrome"@en ;
    skos:definition "Autonomous overproduction of aldosterone by the adrenal glands, due to an adenoma or bilateral hyperplasia, causing sodium and water retention and hypertension; the most common endocrine cause of secondary hypertension and present in up to one in five patients with resistant hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:Pheochromocytoma a owl:Class ;
    rdfs:label "Pheochromocytoma"@en ;
    skos:definition "A tumor causing excessive secretion of norepinephrine and epinephrine, promoting vasoconstriction and secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:CushingSyndrome a owl:Class ;
    rdfs:label "Cushing Syndrome"@en ;
    skos:definition "Excess glucocorticoid activity causing secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:ThyroidDisease a owl:Class ;
    rdfs:label "Thyroid Disease"@en ;
    skos:definition "Hyperthyroidism or hypothyroidism, each recognized as a secondary cause of hypertension, including isolated systolic hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:PrimaryHyperparathyroidism a owl:Class ;
    rdfs:label "Primary Hyperparathyroidism"@en ;
    skos:definition "Excess parathyroid hormone secretion recognized as a contributor to secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:VascularCause a owl:Class ;
    rdfs:label "Vascular Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a structural vascular abnormality."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:AorticCoarctation a owl:Class ;
    rdfs:label "Aortic Coarctation"@en ;
    skos:altLabel "Coarctation of the Aorta"@en ;
    skos:definition "A congenital narrowing of the aorta that produces hypertension and typically affects younger patients."@en ;
    rdfs:subClassOf ht:VascularCause .

ht:ObstructiveSleepApnea a owl:Class ;
    rdfs:label "Obstructive Sleep Apnea"@en ;
    skos:altLabel "OSA"@en ;
    skos:definition "A sleep breathing disorder that is one of the most common causes of secondary hypertension and a common contributor to resistant hypertension."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:DrugInducedCause a owl:Class ;
    rdfs:label "Drug Induced Cause"@en ;
    skos:definition "Secondary hypertension caused by a medication or substance, including NSAIDs, sympathomimetic decongestants, stimulants, corticosteroids, oral contraceptives, immunosuppressants, licorice/carbenoxolone, and recreational stimulants such as cocaine and methamphetamine; may resolve on discontinuation of the agent."@en ;
    rdfs:subClassOf ht:SecondaryCause .

owl:AllDisjointClasses [ owl:members ( ht:RenalCause ht:EndocrineCause ht:VascularCause ht:ObstructiveSleepApnea ht:DrugInducedCause ) ] .

#################################################################
# TARGET ORGAN DAMAGE
#################################################################

ht:TargetOrganDamage a owl:Class ;
    rdfs:label "Target Organ Damage"@en ;
    skos:altLabel "Hypertension-Mediated Organ Damage"@en ;
    skos:definition "Structural or functional injury to the cardiovascular, cerebral, renal, or ocular systems caused by chronic or acutely severe hypertension."@en .

ht:HypertensiveHeartDisease a owl:Class ;
    rdfs:label "Hypertensive Heart Disease"@en ;
    skos:definition "Structural and functional changes in the left ventricle, left atrium, and coronary arteries resulting from chronic blood pressure elevation, including compensatory remodeling, myocyte apoptosis, interstitial fibrosis, and progression to heart failure."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:LeftVentricularHypertrophy a owl:Class ;
    rdfs:label "Left Ventricular Hypertrophy"@en ;
    skos:definition "Thickening of the left ventricular wall in compensatory response to chronic pressure overload; the hallmark structural manifestation of hypertensive heart disease and a strong predictor of cardiovascular events."@en ;
    rdfs:subClassOf ht:HypertensiveHeartDisease .

ht:HypertensiveKidneyDisease a owl:Class ;
    rdfs:label "Hypertensive Kidney Disease"@en ;
    skos:altLabel "Hypertensive Nephropathy"@en , "Nephrosclerosis"@en ;
    skos:definition "Damage to kidney tissue, including small blood vessels, glomeruli, tubules, and interstitium, due to chronic hypertension, causing hardening and thickening of renal tissue (nephrosclerosis), ischemia, and progressive loss of filtering capacity that may culminate in kidney failure."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:HypertensiveEncephalopathy a owl:Class ;
    rdfs:label "Hypertensive Encephalopathy"@en ;
    skos:definition "Acute brain swelling and dysfunction caused by severely elevated blood pressure, presenting with headache, confusion, or visual disturbance; a form of neurological target-organ damage seen in hypertensive emergency."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:HypertensiveRetinopathy a owl:Class ;
    rdfs:label "Hypertensive Retinopathy"@en ;
    skos:definition "Damage to the retina and retinal circulation caused by sustained or abrupt elevations in blood pressure, visible on dilated fundoscopic examination and correlated with the severity and chronicity of systemic hypertension."@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    owl:equivalentClass [ owl:intersectionOf ( ht:TargetOrganDamage
        [ a owl:Restriction ; owl:onProperty ht:hasRetinalFinding ; owl:someValuesFrom ht:RetinalFinding ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveHeartDisease ht:HypertensiveKidneyDisease ht:HypertensiveEncephalopathy ht:HypertensiveRetinopathy ) ] .

ht:hasRetinalFinding a owl:ObjectProperty ;
    rdfs:label "has retinal finding"@en ;
    skos:definition "Relates hypertensive retinopathy to a specific retinal lesion observed on examination."@en ;
    rdfs:domain ht:HypertensiveRetinopathy ; rdfs:range ht:RetinalFinding .

ht:RetinalFinding a owl:Class ;
    rdfs:label "Retinal Finding"@en ;
    skos:definition "A specific retinal lesion observed on fundoscopic examination that characterizes hypertensive retinopathy."@en ;
    rdfs:comment "Severity grades (e.g. Keith-Wagener-Barker Grades 1-4) are not modeled as separate classes; only the named findings themselves are modeled."@en .

ht:ArteriolarNarrowing a owl:Class ;
    rdfs:label "Arteriolar Narrowing"@en ;
    skos:definition "Generalized or focal narrowing of the retinal arterioles, an early finding of hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:ArteriovenousNicking a owl:Class ;
    rdfs:label "Arteriovenous Nicking"@en ;
    skos:altLabel "AV Nipping"@en ;
    skos:definition "Compression of a retinal vein where it is crossed by a sclerotic arteriole, a finding of hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:RetinalHemorrhage a owl:Class ;
    rdfs:label "Retinal Hemorrhage"@en ;
    skos:definition "Bleeding into the retinal tissue, including flame-shaped and blot hemorrhages, resulting from breakdown of the blood-retinal barrier in hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:CottonWoolSpot a owl:Class ;
    rdfs:label "Cotton Wool Spot"@en ;
    skos:definition "A retinal ischemic lesion appearing as a fluffy white patch, seen in moderate to severe hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:HardExudate a owl:Class ;
    rdfs:label "Hard Exudate"@en ;
    skos:definition "Lipid deposits in the retina resulting from leakage through damaged retinal vessels in hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:Papilledema a owl:Class ;
    rdfs:label "Papilledema"@en ;
    skos:altLabel "Optic Disc Edema"@en ;
    skos:definition "Swelling of the optic disc, the most severe retinal finding, indicating malignant hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

owl:AllDisjointClasses [ owl:members ( ht:ArteriolarNarrowing ht:ArteriovenousNicking ht:RetinalHemorrhage ht:CottonWoolSpot ht:HardExudate ht:Papilledema ) ] .

#################################################################
# RISK FACTORS
#################################################################

ht:RiskFactor a owl:Class ;
    rdfs:label "Risk Factor"@en ;
    skos:definition "A factor, modifiable or non-modifiable, associated with increased likelihood of developing hypertension."@en .

ht:ModifiableRiskFactor a owl:Class ;
    rdfs:label "Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that can be altered through behavior change."@en ;
    rdfs:subClassOf ht:RiskFactor .

ht:NonModifiableRiskFactor a owl:Class ;
    rdfs:label "Non Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that cannot be changed by the individual."@en ;
    rdfs:subClassOf ht:RiskFactor .

owl:AllDisjointClasses [ owl:members ( ht:ModifiableRiskFactor ht:NonModifiableRiskFactor ) ] .

ht:ExcessDietarySodium a owl:Class ;
    rdfs:label "Excess Dietary Sodium"@en ;
    skos:altLabel "Excess Salt Intake"@en ;
    skos:definition "Elevated dietary salt intake, recognized as a central modifiable risk factor for hypertension; approximately 50 to 60 percent of hypertensive patients are salt sensitive."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:ExcessBodyWeight a owl:Class ;
    rdfs:label "Excess Body Weight"@en ;
    skos:altLabel "Obesity"@en ;
    skos:definition "Excess body weight, a modifiable risk factor for hypertension; weight reduction alone can lower systolic blood pressure by 5 to 20 mmHg."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:PhysicalInactivity a owl:Class ;
    rdfs:label "Physical Inactivity"@en ;
    skos:definition "Lack of regular exercise, a modifiable risk factor for hypertension."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:TobaccoUse a owl:Class ;
    rdfs:label "Tobacco Use"@en ;
    skos:altLabel "Smoking"@en ;
    skos:definition "Use of tobacco products, a modifiable risk factor for hypertension."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:ExcessAlcoholConsumption a owl:Class ;
    rdfs:label "Excess Alcohol Consumption"@en ;
    skos:definition "Drinking alcohol in excess, a modifiable risk factor associated with higher blood pressure."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:AdvancedAge a owl:Class ;
    rdfs:label "Advanced Age"@en ;
    skos:definition "Older age, a major non-modifiable risk factor for hypertension; prevalence rises to approximately 60 percent of individuals above age 60."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:FamilyHistory a owl:Class ;
    rdfs:label "Family History"@en ;
    skos:definition "A family history of hypertension, a non-modifiable risk factor reflecting genetic predisposition."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:Race a owl:Class ;
    rdfs:label "Race"@en ;
    skos:definition "Race or ethnicity, a non-modifiable risk factor that also influences first-line antihypertensive drug selection."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:GeneticPredisposition a owl:Class ;
    rdfs:label "Genetic Predisposition"@en ;
    skos:definition "Inherited genetic variants influencing individual salt sensitivity and blood pressure regulation; more than 2,000 common genetic variants with small effects on blood pressure have been identified."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:hasRiskFactor a owl:ObjectProperty ;
    rdfs:label "has risk factor"@en ;
    skos:definition "Relates hypertension to a modifiable or non-modifiable risk factor associated with its development."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:RiskFactor .

#################################################################
# ANTIHYPERTENSIVE DRUG CLASSES
#################################################################

ht:Antihypertensive a owl:Class ;
    rdfs:label "Antihypertensive"@en ;
    skos:definition "A class of medication used to lower blood pressure."@en .

ht:ThiazideDiuretic a owl:Class ;
    rdfs:label "Thiazide Diuretic"@en ;
    skos:altLabel "Thiazide-Type Diuretic"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks sodium reabsorption at the sodium-chloride cotransporter in the distal convoluted tubule, promoting natriuresis and diuresis and causing modest vasodilation; includes thiazide and thiazide-like agents such as chlorthalidone and indapamide."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:AngiotensinConvertingEnzymeInhibitor a owl:Class ;
    rdfs:label "Angiotensin Converting Enzyme Inhibitor"@en ;
    skos:altLabel "ACE Inhibitor"@en , "ACEI"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits angiotensin-converting enzyme, reducing angiotensin II production and increasing bradykinin, thereby causing vasodilation; preferred in patients with diabetes, chronic kidney disease, or heart failure; contraindicated in pregnancy."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:AngiotensinReceptorBlocker a owl:Class ;
    rdfs:label "Angiotensin Receptor Blocker"@en ;
    skos:altLabel "ARB"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks the binding of angiotensin II to the AT1 receptor, with efficacy similar to ACE inhibitors but a much lower incidence of cough and angioedema; generally not combined with ACE inhibitors."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:CalciumChannelBlocker a owl:Class ;
    rdfs:label "Calcium Channel Blocker"@en ;
    skos:altLabel "CCB"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits calcium entry through L-type voltage-gated calcium channels in cardiac and vascular smooth muscle."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:Dihydropyridine a owl:Class ;
    rdfs:label "Dihydropyridine"@en ;
    skos:definition "A subtype of calcium channel blocker that acts predominantly on vascular smooth muscle to cause peripheral vasodilation; preferred for treating hypertension."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

ht:NonDihydropyridine a owl:Class ;
    rdfs:label "Non Dihydropyridine"@en ;
    skos:definition "A subtype of calcium channel blocker, such as verapamil and diltiazem, that primarily affects cardiac contractility and atrioventricular conduction, better suited to managing arrhythmias."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

owl:AllDisjointClasses [ owl:members ( ht:Dihydropyridine ht:NonDihydropyridine ) ] .

ht:BetaBlocker a owl:Class ;
    rdfs:label "Beta Blocker"@en ;
    skos:definition "An antihypertensive drug class that inhibits catecholamines from binding to beta-adrenergic receptors, decreasing heart rate, myocardial contractility, and renin release; no longer first-line for uncomplicated hypertension but retained for patients with a compelling cardiac indication."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:MineralocorticoidReceptorAntagonist a owl:Class ;
    rdfs:label "Mineralocorticoid Receptor Antagonist"@en ;
    skos:altLabel "MRA"@en ;
    skos:definition "A drug class, such as spironolactone, that antagonizes the mineralocorticoid receptor; commonly added for resistant hypertension and used to treat primary aldosteronism."@en ;
    rdfs:subClassOf ht:Antihypertensive .

owl:AllDisjointClasses [ owl:members ( ht:ThiazideDiuretic ht:AngiotensinConvertingEnzymeInhibitor ht:AngiotensinReceptorBlocker ht:CalciumChannelBlocker ht:BetaBlocker ht:MineralocorticoidReceptorAntagonist ) ] .

ht:hasAntihypertensive a owl:ObjectProperty ;
    rdfs:label "has antihypertensive"@en ;
    skos:definition "Relates hypertension to an antihypertensive drug class used in its management."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:Antihypertensive .

ht:isAntihypertensiveOf a owl:ObjectProperty ;
    rdfs:label "is antihypertensive of"@en ;
    skos:definition "Inverse of has antihypertensive."@en ;
    owl:inverseOf ht:hasAntihypertensive ;
    rdfs:domain ht:Antihypertensive ; rdfs:range ht:Hypertension .
